            ["Reiniciar agora"] = "Restart now",
            ["OK"] = "OK",
            ["O PC vai reiniciar em 15 segundos. Salve o que estiver aberto.\n\nReiniciar agora?"] = "The PC will restart in 15 seconds. Save whatever is open.\n\nRestart now?",
            ["Não consegui reiniciar: {0}"] = "Couldn't restart: {0}",
