            ["Nada a limpar"] = "Nothing to clean",
            ["LIMPEZA"] = "CLEANUP",
            ["Primeiro o GBooster analisa o que dá para apagar e mostra o tamanho. Nada é apagado até você escolher e clicar em Limpar."] = "First GBooster analyzes what can be deleted and shows the size. Nothing is deleted until you choose and click Clean.",
            ["Analisar"] = "Analyze",
            ["Feche o jogo para limpar."] = "Close the game to clean.",
            ["ANALISANDO…"] = "ANALYZING…",
            ["Procurando arquivos que podem ser apagados. Nada é apagado agora."] = "Looking for files that can be deleted. Nothing is deleted now.",
            ["Limpar selecionados"] = "Clean selected",
            ["Nada selecionado"] = "Nothing selected",
