            ["PODE SER LIMPO"] = "CAN BE CLEANED",
            ["Marcar todos"] = "Select all",
            ["Desmarcar todos"] = "Clear all",
            ["Analisar de novo"] = "Analyze again",
            ["Isso apaga os pontos de restauração antigos, menos o mais recente. Depois não dá para voltar o Windows a essas datas.\n\nContinuar?"] = "This deletes the old restore points, except the most recent one. Afterwards you can't take Windows back to those dates.\n\nContinue?",
            ["LIMPANDO…"] = "CLEANING…",
            ["Pode levar alguns minutos"] = "May take a few minutes",
            ["Limpeza interrompida"] = "Cleanup interrupted",
            ["Limpeza concluída"] = "Cleanup finished",
            ["{0} liberados"] = "{0} freed",
            ["LIMPEZA INTERROMPIDA"] = "CLEANUP INTERRUPTED",
            ["Um jogo foi aberto e a limpeza parou para não atrapalhar."] = "A game was opened and the cleanup stopped so as not to get in the way.",
            ["{0} liberados até aqui."] = "{0} freed so far.",
            ["LIMPEZA CONCLUÍDA"] = "CLEANUP FINISHED",
