            ["Limpo · {0}"] = "Cleaned · {0}",
            ["Limpo"] = "Cleaned",
            ["Não selecionado"] = "Not selected",
            ["Cache do Google Chrome"] = "Google Chrome cache",
            ["Cache do Microsoft Edge"] = "Microsoft Edge cache",
            ["Cache do Mozilla Firefox"] = "Mozilla Firefox cache",
            ["Só imagens e arquivos temporários dos sites. Não apaga histórico, senhas, cookies nem logins."] = "Only website images and temporary files. Doesn't delete history, passwords, cookies or logins.",
            ["Cache do Discord"] = "Discord cache",
            ["Imagens e arquivos temporários. O Discord refaz na próxima abertura; você continua logado."] = "Images and temporary files. Discord rebuilds it next time it opens; you stay signed in.",
            ["Cache da Steam"] = "Steam cache",
            ["Páginas da loja e da comunidade guardadas no app. Não mexe nos jogos nem nos salvamentos."] = "Store and community pages saved in the app. Doesn't touch your games or saves.",
            ["Precisa do modo administrador. Reiniciar como administrador"] = "Needs administrator mode. Restart as administrator",
            ["COMO O APP FUNCIONA E CUIDADOS"] = "HOW THE APP WORKS AND CAUTIONS",
            ["Troca de tela"] = "Screen switching",
            ["Quando o jogo abre, o app troca a resolução e a saturação do monitor e devolve tudo ao fechar. Ele só confere quais programas estão abertos: não lê nem altera o jogo e não injeta código."] = "When the game opens, the app changes the monitor resolution and saturation and puts everything back when it closes. It only checks which programs are running: it doesn't read or alter the game and doesn't inject code.",
            ["Notebook"] = "Laptop",
            ["Tela sempre ligada, PCIe sem economia e timing de 0,5 ms gastam mais bateria e esquentam mais."] = "Screen always on, no PCIe power saving and the 0.5 ms timing use more battery and run hotter.",
            ["Outras ferramentas"] = "Other tools",
            ["ISLC, Wub, Timer Resolution e MSI util, se continuarem abertas ou instaladas, podem disputar os mesmos ajustes com o GBooster."] = "ISLC, Wub, Timer Resolution and MSI util, if left open or installed, may fight GBooster over the same settings.",
            ["App da NVIDIA"] = "NVIDIA app",
            ["O app da NVIDIA ou o GeForce Experience com “otimizar jogos” ligado pode sobrescrever o perfil dos jogos."] = "The NVIDIA app or GeForce Experience with “optimize games” on can overwrite the game profiles.",
            ["Atualizações do Windows"] = "Windows updates",
            ["Atualizações grandes podem desfazer parte dos ajustes. O selo da página Desempenho mostra o estado real."] = "Big updates can undo part of the tweaks. The badge on the Performance page shows the real state.",
            ["Modo MSI"] = "MSI mode",
            ["Na placa de vídeo e no USB, em poucos PCs, causa chiado no áudio ou travadas. Dá para desfazer, mas pede reinício."] = "On the graphics card and USB, on a few PCs, it causes audio crackle or stutters. It can be undone, but needs a restart.",
            ["HDD no lugar de SSD"] = "HDD instead of SSD",
            ["Abrir programas pode ficar um pouco mais lento sem o Superfetch."] = "Opening programs may be a bit slower without Superfetch.",
            ["Ajuda"] = "Help",
            ["Voltar"] = "Back",
            ["O que o GBooster faz"] = "What GBooster does",
            ["Troca de tela, ajustes do Windows, limpeza e informações do PC."] = "Screen switching, Windows tweaks, cleanup and PC information.",
            ["Troca de tela por jogo"] = "Screen switching per game",
            ["Quando um jogo cadastrado abre, o app troca a resolução do monitor (e, se você quiser, a taxa de atualização e a saturação) e devolve tudo ao fechar o jogo."] = "When a registered game opens, the app changes the monitor resolution (and, if you want, the refresh rate and saturation) and puts everything back when the game closes.",
            ["Desempenho"] = "Performance",
            ["Aplica 12 ajustes do Windows de uma vez, com ponto de restauração e Desfazer. Só roda quando você clica em Otimizar."] = "Applies 12 Windows tweaks at once, with a restore point and Undo. It only runs when you click Optimize.",
            ["Limpeza"] = "Cleanup",
            ["Analisa e mostra o tamanho de temporários e caches, e só apaga o que você marcar."] = "Analyzes and shows the size of temp files and caches, and only deletes what you tick.",
            ["Meu sistema"] = "My system",
            ["Mostra processador, memória, placa de vídeo, discos e Windows, e mede o timing do Windows. Só leitura: nada é alterado."] = "Shows processor, memory, graphics card, disks and Windows, and measures Windows timing. Read-only: nothing is changed.",
            ["Como funciona e segurança"] = "How it works and safety",
            ["O que o app faz e o que ele nunca faz."] = "What the app does and what it never does.",
            ["Não toca no jogo"] = "Doesn't touch the game",
            ["Só confere quais programas estão abertos. Não abre o processo do jogo, não lê nem escreve na memória e não injeta código."] = "It only checks which programs are running. It doesn't open the game process, doesn't read or write memory and doesn't inject code.",
            ["Sem internet, conta ou telemetria"] = "No internet, account or telemetry",
            ["Nada sai do seu computador. Os dados ficam na pasta GBooster, dentro do AppData."] = "Nothing leaves your computer. Data stays in the GBooster folder inside AppData.",
            ["Volta ao normal"] = "Goes back to normal",
            ["A tela volta ao normal ao fechar o jogo, ao usar Restaurar resolução agora (na janela ou na bandeja) ou ao fechar o app. Se o PC cair, o app desfaz na próxima abertura."] = "The screen goes back to normal when the game closes, with Restore resolution now (in the window or the tray) or when the app closes. If the PC crashes, the app undoes it on the next start.",
            ["Ajustes do Windows são desfeitos por você"] = "Windows tweaks are undone by you",
            ["Cada ajuste guarda o valor de antes. O botão Desfazer otimizações devolve tudo, menos os apps do Windows removidos."] = "Each tweak saves the previous value. The Undo optimizations button restores everything, except removed Windows apps.",
            ["O que precisa"] = "What you need",
            ["Requisitos e quando é preciso ser administrador."] = "Requirements and when administrator mode is needed.",
            ["Windows 10 ou 11, 64 bits"] = "Windows 10 or 11, 64-bit",
            ["Não precisa instalar o .NET."] = "No need to install .NET.",
            ["Modo administrador"] = "Administrator mode",
            ["Necessário para otimizar, pausar atualizações, criar ponto de restauração e alguns itens da Limpeza. A troca de tela funciona sem isso."] = "Needed to optimize, pause updates, create a restore point and some Cleanup items. Screen switching works without it.",
            ["Placa NVIDIA"] = "NVIDIA card",
            ["Só a saturação e o perfil da NVIDIA dependem dela. O resto funciona em qualquer placa."] = "Only saturation and the NVIDIA profile depend on it. Everything else works on any card.",
            ["Escala “Tela inteira”"] = "“Full screen” scaling",
            ["Para a resolução esticada ocupar a tela toda, sem barras pretas, ative essa escala nas configurações da placa de vídeo."] = "For the stretched resolution to fill the whole screen with no black bars, turn on this scaling in your graphics card settings.",
            ["Para quem é"] = "Who it's for",
            ["Quem joga competitivo e quer mais fluidez."] = "Competitive players who want smoother gameplay.",
            ["Jogadores competitivos"] = "Competitive players",
            ["Quem usa resolução diferente da nativa e cansou de trocar nas configurações do Windows toda vez que abre e fecha o jogo."] = "People who use a non-native resolution and are tired of changing it in Windows settings every time they open and close a game.",
            ["Quem quer o PC mais leve para jogar"] = "Anyone who wants a lighter PC for gaming",
            ["Os ajustes do Desempenho e a Limpeza reduzem o que roda em segundo plano e liberam espaço."] = "The Performance tweaks and Cleanup reduce background activity and free up space.",
            ["Cuidados e compatibilidade"] = "Cautions and compatibility",
            ["O que pode acontecer em alguns PCs."] = "What can happen on some PCs.",
            ["Anti-cheat"] = "Anti-cheat",
            ["Nenhuma desenvolvedora publica uma lista de programas permitidos. O app não faz o que as regras públicas proíbem, mas a decisão final é do anti-cheat. A saturação é a parte mais sensível: use por sua conta e risco."] = "No developer publishes a list of allowed programs. The app doesn't do what the public rules forbid, but the final decision is the anti-cheat's. Saturation is the most sensitive part: use it at your own risk.",
            ["Notebook"] = "Laptop",
            ["Tela sempre ligada, PCIe sem economia e timing de 0,5 ms gastam mais bateria e esquentam mais."] = "Screen always on, no PCIe power saving and the 0.5 ms timing use more battery and run hotter.",
            ["Outras ferramentas"] = "Other tools",
            ["ISLC, Wub, Timer Resolution e MSI util, se continuarem abertas ou instaladas, podem disputar os mesmos ajustes com o GBooster."] = "ISLC, Wub, Timer Resolution and MSI util, if left open or installed, may fight GBooster over the same settings.",
            ["App da NVIDIA"] = "NVIDIA app",
            ["O app da NVIDIA ou o GeForce Experience com “otimizar jogos” ligado pode sobrescrever o perfil dos jogos."] = "The NVIDIA app or GeForce Experience with “optimize games” on can overwrite the game profiles.",
            ["Atualizações do Windows"] = "Windows updates",
