            ["O WINDOWS DESFEZ AJUSTES"] = "WINDOWS UNDID TWEAKS",
            ["1 ajuste voltou ao padrão, provavelmente por uma atualização do Windows:"] = "1 tweak went back to default, probably because of a Windows update:",
            ["{0} ajustes voltaram ao padrão, provavelmente por uma atualização do Windows:"] = "{0} tweaks went back to default, probably because of a Windows update:",
