            ["Marque ao menos um ajuste na lista “O que otimizar”."] = "Select at least one tweak in the “What to optimize” list.",
            ["{0} ajustes seguros. Abra para ver e escolher."] = "{0} safe tweaks. Open to see and choose.",
            ["{0} de {1} marcados · {2} já aplicados. Abra para ver e escolher."] = "{0} of {1} selected · {2} already applied. Open to see and choose.",
            ["O que otimizar"] = "What to optimize",
            ["Desmarcar um ajuste só o tira do próximo Otimizar: o que já foi aplicado continua. Para voltar atrás, use Desfazer otimizações."] = "Unchecking a tweak only removes it from the next Optimize: what was already applied stays. To go back, use Undo optimizations.",
